def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    color_by_inner_size = {3: 8, 5: 4, 7: 3}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            top = min(x for x, y in comp)
            bottom = max(x for x, y in comp)
            left = min(y for x, y in comp)
            right = max(y for x, y in comp)
            ih, iw = bottom - top - 1, right - left - 1
            if ih != iw or ih not in color_by_inner_size:
                continue

            perimeter = set()
            for y in range(left, right + 1):
                perimeter.add((top, y))
                perimeter.add((bottom, y))
            for x in range(top, bottom + 1):
                perimeter.add((x, left))
                perimeter.add((x, right))
            if set(comp) != perimeter:
                continue

            fill = color_by_inner_size[ih]
            for x in range(top + 1, bottom):
                for y in range(left + 1, right):
                    if out[x][y] == 0:
                        out[x][y] = fill

    return out
